"use client";

import { FC } from "react";
import { cn } from "@/lib/utils";
import { Navigation, Car, PersonStanding, Train, Bike, MapPin, Clock, ArrowRight, ExternalLink } from "lucide-react";
import { ActionButtons } from "@/components/tool-ui/shared/action-buttons";
import { RATIO_CLASS_MAP, getFitClass } from "@/components/tool-ui/shared/media";
import type { SerializableMaps } from "./schema";

interface MapsProps extends SerializableMaps {
  className?: string;
  onResponseAction?: (actionId: string) => void;
}

const getModeIcon = (mode: string) => {
  switch (mode) {
    case "driving":
      return <Car className="w-4 h-4" />;
    case "walking":
      return <PersonStanding className="w-4 h-4" />;
    case "transit":
      return <Train className="w-4 h-4" />;
    case "bicycling":
      return <Bike className="w-4 h-4" />;
    default:
      return <Navigation className="w-4 h-4" />;
  }
};

const getModeLabel = (mode: string) => {
  switch (mode) {
    case "driving":
      return "Driving";
    case "walking":
      return "Walking";
    case "transit":
      return "Transit";
    case "bicycling":
      return "Bicycling";
    default:
      return "Navigation";
  }
};

// Generate Google Maps directions URL
const generateGoogleMapsUrl = (
  destination: string,
  origin?: string,
  mode: string = "driving"
): string => {
  const params = new URLSearchParams({
    api: "1",
    destination: destination,
  });

  // Add origin if provided, otherwise defaults to current location
  if (origin) {
    params.append("origin", origin);
  }

  // Map component modes to Google Maps travel modes
  const travelModeMap: Record<string, string> = {
    driving: "driving",
    walking: "walking",
    transit: "transit",
    bicycling: "bicycling",
  };

  params.append("travelmode", travelModeMap[mode] || "driving");

  return `https://www.google.com/maps/dir/?${params.toString()}`;
};

export const Maps: FC<MapsProps> = ({
  id,
  destination,
  origin,
  mode = "driving",
  title,
  description,
  distance,
  duration,
  mapImageUrl,
  ratio = "16:9",
  responseActions,
  className,
  onResponseAction,
}) => {
  // Handle clicking the map card to open directions from Paris
  const handleMapClick = () => {
    const defaultOrigin = "Paris, France";
    const mapsUrl = generateGoogleMapsUrl(destination, origin || defaultOrigin, mode);
    window.open(mapsUrl, "_blank", "noopener,noreferrer");
  };

  // Handle action clicks
  const handleAction = (actionId: string) => {
    // Check if this is a maps-related action
    const mapsActions = ["open-maps", "get-directions", "directions", "open-google-maps"];

    if (mapsActions.includes(actionId)) {
      const mapsUrl = generateGoogleMapsUrl(destination, origin || "Paris, France", mode);
      window.open(mapsUrl, "_blank", "noopener,noreferrer");
    }

    // Call the original handler if provided
    if (onResponseAction) {
      onResponseAction(actionId);
    }
  };

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-tool-ui-id={id}
      data-slot="maps"
    >
      <div
        className="bg-secondary text-primary border  rounded-lg overflow-hidden hover:scale-[1.01] transition-transform cursor-pointer"
        onClick={handleMapClick}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleMapClick();
          }
        }}
      >
        {/* Map Image Preview */}
        {mapImageUrl && (
          <div className={cn("relative overflow-hidden bg-gradient-to-br from-gray-900 to-black", RATIO_CLASS_MAP[ratio])}>
            <img
              src={mapImageUrl}
              alt={title || destination}
              className="w-full h-full object-cover "

              loading="lazy"
              onError={(e) => {
                e.currentTarget.style.display = 'none';
              }}
            />
          </div>
        )}

        {/* Content */}
        <div className="p-3 space-y-2">
          {/* Header: Mode + Distance/Duration */}
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-1.5 text-xs font-medium text-gray-400">
              <div className="flex items-center gap-1 px-2 py-0.5 bg-gray-800 rounded-md">
                {getModeIcon(mode)}
                <span>{getModeLabel(mode)}</span>
              </div>
            </div>

            <div className="flex items-center gap-2">
              {(distance || duration) && (
                <div className="flex items-center gap-2 text-xs text-gray-400">
                  {duration && (
                    <div className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      <span className="font-medium">{duration}</span>
                    </div>
                  )}
                  {distance && duration && <span>•</span>}
                  {distance && (
                    <span className="font-medium">{distance}</span>
                  )}
                </div>
              )}
              <ExternalLink className="w-3.5 h-3.5 text-gray-500" />
            </div>
          </div>

          {/* Title */}
          {title && (
            <h3 className="font-semibold text-sm leading-tight line-clamp-1">
              {title}
            </h3>
          )}

          {/* Destination */}
          <div className="flex items-start gap-2">
            <MapPin className="w-3.5 h-3.5 flex-shrink-0 text-blue-400 mt-0.5" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium line-clamp-2 leading-snug">
                {destination}
              </p>
              {origin && (
                <p className="text-xs text-gray-400 mt-0.5 line-clamp-1">
                  from {origin}
                </p>
              )}
            </div>
          </div>

          {/* Description */}
          {description && (
            <p className="text-xs text-gray-400 line-clamp-2 leading-relaxed">
              {description}
            </p>
          )}
        </div>
      </div>

      {/* Response Actions */}
      {responseActions && responseActions.length > 0 && (
        <ActionButtons
          actions={responseActions}
          onAction={handleAction}
        />
      )}
    </div>
  );
};

import type { Action } from "../shared/schema";

export interface SerializableMaps {
  id: string;
  destination: string;
  origin?: string;
  mode?: "driving" | "walking" | "transit" | "bicycling";
  title?: string;
  description?: string;
  distance?: string;
  duration?: string;
  mapImageUrl?: string;
  ratio?: "auto" | "1:1" | "4:3" | "16:9" | "9:16";
  responseActions?: Action[];
}

export function parseSerializableMaps(data: any): SerializableMaps {
  // Check if data is in the complex format with markers and routes
  if (data.markers && Array.isArray(data.markers)) {
    // Extract destination and origin from markers
    const originMarker = data.markers.find((m: any) =>
      m.id?.includes('origin') || m.label?.toLowerCase().includes('vous') || m.label?.toLowerCase().includes('you')
    );
    const destMarker = data.markers.find((m: any) =>
      m.id?.includes('destination') || m.id?.includes('dest') || (!m.id?.includes('origin') && m !== originMarker)
    );

    // Build destination and origin strings from marker labels and coordinates
    const destination = destMarker
      ? `${destMarker.label || 'Destination'} (${destMarker.lat}, ${destMarker.lng})`
      : data.destination || "";

    const origin = originMarker
      ? `${originMarker.label || 'Origin'} (${originMarker.lat}, ${originMarker.lng})`
      : data.origin;

    return {
      id: data.id || crypto.randomUUID(),
      destination,
      origin,
      mode: data.mode || "driving",
      title: data.title,
      description: data.description,
      distance: data.distance,
      duration: data.duration,
      mapImageUrl: data.mapImageUrl,
      ratio: data.ratio || "16:9",
      responseActions: data.responseActions,
    };
  }

  // Standard format
  return {
    id: data.id || crypto.randomUUID(),
    destination: data.destination || "",
    origin: data.origin,
    mode: data.mode || "driving",
    title: data.title,
    description: data.description,
    distance: data.distance,
    duration: data.duration,
    mapImageUrl: data.mapImageUrl,
    ratio: data.ratio || "16:9",
    responseActions: data.responseActions,
  };
}

"use client";

import { FC } from "react";
import { Button } from "@/components/ui/button";
import type { Action } from "./schema";

interface ActionButtonsProps {
  actions?: Action[];
  onAction?: (actionId: string) => void;
  className?: string;
}

export const ActionButtons: FC<ActionButtonsProps> = ({
  actions,
  onAction,
  className,
}) => {
  if (!actions || actions.length === 0) return null;

  return (
    <div className={`flex flex-wrap gap-2 ${className || ""}`}>
      {actions.map((action) => (
        <Button
          key={action.id}
          variant={action.variant || "outline"}
          size="sm"
          disabled={action.disabled}
          onClick={() => onAction?.(action.id)}
          className="text-xs"
        >
          {action.label}
        </Button>
      ))}
    </div>
  );
};

export const RATIO_CLASS_MAP = {
  auto: "aspect-auto",
  "1:1": "aspect-square",
  "4:3": "aspect-[4/3]",
  "16:9": "aspect-video",
  "9:16": "aspect-[9/16]",
} as const;

export function getFitClass(fit: "cover" | "contain" = "cover") {
  return fit === "cover" ? "object-cover" : "object-contain";
}

export const OVERLAY_GRADIENT =
  "bg-gradient-to-t from-black/60 via-black/20 to-transparent";

export function sanitizeHref(href: string | undefined): string | undefined {
  if (!href) return undefined;
  try {
    const url = new URL(href);
    if (url.protocol === "javascript:") return undefined;
    return href;
  } catch {
    return undefined;
  }
}

/**
 * Shared types for social post components
 */

export interface Action {
  id: string;
  label: string;
  prompt?: string; // The message to send when clicked
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
  disabled?: boolean;
}

export interface BaseAuthor {
  name: string;
  avatarUrl: string;
}

export interface MediaItem {
  type: "image" | "video";
  url: string;
  alt?: string;
  aspectRatio?: number;
}

export interface LinkPreview {
  url: string;
  title?: string;
  description?: string;
  imageUrl?: string;
  domain?: string;
}

export interface BaseStats {
  likes?: number;
  shares?: number;
  comments?: number;
}
